  ('df62fafa-0055-c917-50e8-aa130ed43ef4', 'Helaena Targaryen', 'person', '[{"points": 10, "category_id": 1, "category_name": "First Named Character to Die"}, {"points": 10, "category_id": 4, "category_name": "Whose Dragon Falls"}, {"points": 10, "category_id": 5, "category_name": "The Cliffhanger Centers On"}, {"points": 8, "category_id": 7, "category_name": "Last Character On Screen"}, {"points": 8, "category_id": 11, "category_name": "Ends in the Worst Position"}, {"points": 8, "category_id": 12, "category_name": "Claims a Dragon"}, {"points": 6, "category_id": 13, "category_name": "First to Ride a Dragon"}, {"points": 6, "category_id": 16, "category_name": "Survives Against All Odds"}, {"points": 4, "category_id": 18, "category_name": "First to Cry"}]', 'The Greens', '9'),
  ('efe00b8c-9fe1-0136-54f3-e152d78a8ec4', 'Alyn of Hull', 'person', '[{"points": 10, "category_id": 1, "category_name": "First Named Character to Die"}, {"points": 10, "category_id": 2, "category_name": "Most On-Screen Kills"}, {"points": 10, "category_id": 6, "category_name": "Wins the Battle"}, {"points": 8, "category_id": 7, "category_name": "Last Character On Screen"}, {"points": 8, "category_id": 9, "category_name": "First Blood"}, {"points": 6, "category_id": 16, "category_name": "Survives Against All Odds"}, {"points": 4, "category_id": 17, "category_name": "First Line of Dialogue"}]', 'Velaryon Camp', '7'),
  ('f0b703a0-c333-b1fb-2cdd-aced8451e3aa', 'Moondancer', 'film', '[{"points": 10, "category_id": 4, "category_name": "Whose Dragon Falls"}, {"points": 10, "category_id": 6, "category_name": "Wins the Battle"}, {"points": 6, "category_id": 13, "category_name": "First to Ride a Dragon"}, {"points": 6, "category_id": 16, "category_name": "Survives Against All Odds"}]', 'Moondancer', '4'),
  ('ff493811-9199-ddd5-71f1-0ba7cbede994', 'Alysanne Blackwood', 'person', '[{"points": 10, "category_id": 1, "category_name": "First Named Character to Die"}, {"points": 10, "category_id": 2, "category_name": "Most On-Screen Kills"}, {"points": 10, "category_id": 6, "category_name": "Wins the Battle"}, {"points": 8, "category_id": 9, "category_name": "First Blood"}, {"points": 6, "category_id": 16, "category_name": "Survives Against All Odds"}, {"points": 4, "category_id": 19, "category_name": "Most Menacing Stare"}]', 'The North and Riverlands', '6')
insert into public.bingo_squares ("id", "text", "short_text", "is_objective", "slug", "title", "category", "probability_pct", "likelihood_tier", "win_condition", "why_it_is_fun", "storyline_tags", "fun_type") values
  ('1', 'A dragon must unmistakably die during the episode or be definitively confirmed dead. A crash, disappearance, or catastrophic-looking injury does not count unless the episode establishes the death.', 'Dragon Dies', 'false', 'dragon_dies', 'Dragon Dies', 'dragons', '65', 'likely', 'A dragon must unmistakably die during the episode or be definitively confirmed dead. A crash, disappearance, or catastrophic-looking injury does not count unless the episode establishes the death.', 'A huge, visually obvious payoff with real stakes; strong enough to anchor a board without being guaranteed.', '{dragons,combat,death}', 'spectacle'),
  ('10', 'Vhagar must make a substantial present-day appearance that materially changes the mood or action of a scene. A distant glimpse, memory, or prophetic vision does not count.', 'Vhagar Entrance', 'false', 'vhagar_entrance', 'Vhagar Entrance', 'dragons', '50', 'toss_up', 'Vhagar must make a substantial present-day appearance that materially changes the mood or action of a scene. A distant glimpse, memory, or prophetic vision does not count.', 'Vhagar entering any scene instantly changes the threat level.', '{aemond,vhagar,greens}', 'spectacle'),
  ('11', 'Something genuinely positive must happen for Sheepstealer: escape, recovery, protection, reunion, food, or survival from a fresh threat. More suffering does not count; the point is that the poor dragon gets a win.', 'Sheepstealer Justice', 'false', 'sheepstealer_justice', 'Sheepstealer Justice', 'dragons', '45', 'toss_up', 'Something genuinely positive must happen for Sheepstealer: escape, recovery, protection, reunion, food, or survival from a fresh threat. More suffering does not count; the point is that the poor dragon gets a win.', 'Directly taps the audience''s unexpectedly protective reaction to Sheepstealer after episode 7.', '{rhaena,sheepstealer,blacks}', 'audience-love'),
  ('12', 'Dreamfyre must visibly appear again, either physically or unmistakably within Helaena''s prophetic experience. A spoken reference to Dreamfyre alone does not count.', 'Dreamfyre Appears', 'false', 'dreamfyre_appears', 'Dreamfyre Appears', 'dragons', '50', 'toss_up', 'Dreamfyre must visibly appear again, either physically or unmistakably within Helaena''s prophetic experience. A spoken reference to Dreamfyre alone does not count.', 'Fans finally got a meaningful Dreamfyre reveal in episode 7, making any follow-up instantly notable.', '{helaena,dreamfyre,visions}', 'audience-love'),
  ('13', 'A dragon must receive a clearly visible new injury during the finale. Existing scars or wounds carried into the episode do not count.', 'Dragon Wounded', 'false', 'dragon_wounded', 'Dragon Wounded', 'dragons', '55', 'toss_up', 'A dragon must receive a clearly visible new injury during the finale. Existing scars or wounds carried into the episode do not count.', 'Broad enough to be viable but still gives the board a concrete visual event.', '{dragons,combat,injury}', 'spectacle'),
  ('14', 'A rider must have an unmistakably affectionate physical interaction with their dragon, such as embracing, nuzzling, stroking, or comforting it. Mounting or handling tack does not count.', 'Dragon Hug', 'false', 'dragon_hug', 'Dragon Hug', 'dragons', '25', 'long_shot', 'A rider must have an unmistakably affectionate physical interaction with their dragon, such as embracing, nuzzling, stroking, or comforting it. Mounting or handling tack does not count.', 'A rare wholesome square in a show where almost everything else is on fire.', '{dragons,riders,bond}', 'audience-love'),
  ('15', 'A dragon must visibly kill and eat, bite apart, or swallow a named character. Burning a named character without actually using its teeth does not count.', 'Named Dragon Snack', 'false', 'dragon_eats_name', 'Named Dragon Snack', 'dragons', '12', 'chaos', 'A dragon must visibly kill and eat, bite apart, or swallow a named character. Burning a named character without actually using its teeth does not count.', 'A true chaos square: low probability, incredibly memorable, and worth screaming about.', '{dragons,death,named-character}', 'chaos'),
  ('16', 'Rhaena must make an identifiable decision that clearly worsens the situation. Bad luck by itself does not count; viewers should reasonably be able to say, “Rhaena, why did you do that?”', 'Rhaena Screws Up', 'false', 'rhaena_screws_up', 'Rhaena Screws Up', 'black_court', '55', 'toss_up', 'Rhaena must make an identifiable decision that clearly worsens the situation. Bad luck by itself does not count; viewers should reasonably be able to say, “Rhaena, why did you do that?”', 'Turns the group''s frustration with her into a recurring comedy bet instead of just complaining about the character.', '{rhaena,sheepstealer,blacks}', 'audience-hate'),
  ('17', 'Rhaena must try to reconnect with or control Sheepstealer, and Sheepstealer must actively avoid, threaten, ignore, or reject her. Remaining separated without an attempted interaction does not count.', 'Sheepstealer Rejects', 'false', 'sheepstealer_rejects', 'Sheepstealer Rejects', 'black_court', '35', 'long_shot', 'Rhaena must try to reconnect with or control Sheepstealer, and Sheepstealer must actively avoid, threaten, ignore, or reject her. Remaining separated without an attempted interaction does not count.', 'Specific payoff to the season-long question of whether Rhaena can actually control the dragon she claimed.', '{rhaena,sheepstealer}', 'character-comedy'),
  ('18', 'Another named character must directly blame or seriously criticize Rhaena for Sheepstealer, Jace, the Gullet, or her choices this season. Rhaena blaming herself does not satisfy this square.', 'Rhaena Gets Blamed', 'false', 'rhaena_gets_blamed', 'Rhaena Gets Blamed', 'black_court', '45', 'toss_up', 'Another named character must directly blame or seriously criticize Rhaena for Sheepstealer, Jace, the Gullet, or her choices this season. Rhaena blaming herself does not satisfy this square.', 'A satisfying callback square that requires the season''s consequences to be spoken aloud.', '{rhaena,jace,gullet,callback}', 'audience-hate'),
  ('19', 'Baela must visibly or verbally react to Rhaena with clear annoyance, disbelief, frustration, or judgment. The reaction should be obvious enough that it does not require frame-by-frame interpretation.', 'Baela Side-Eye', 'false', 'baela_side_eye', 'Baela Side-Eye', 'black_court', '50', 'toss_up', 'Baela must visibly or verbally react to Rhaena with clear annoyance, disbelief, frustration, or judgment. The reaction should be obvious enough that it does not require frame-by-frame interpretation.', 'Small, funny, character-specific, and easy to catch during a live watch.', '{baela,rhaena,blacks}', 'character-comedy'),
  ('2', 'Two dragons must deliberately attack one another. Roaring, posturing, chasing without contact, or simply sharing a battlefield does not count.', 'Dragon vs Dragon', 'false', 'dragon_vs_dragon', 'Dragon vs Dragon', 'dragons', '70', 'likely', 'Two dragons must deliberately attack one another. Roaring, posturing, chasing without contact, or simply sharing a battlefield does not count.', 'Easy to judge in real time and exactly the kind of finale spectacle people want.', '{dragons,combat}', 'spectacle'),
  ('20', 'A current decision or confrontation involving Rhaena, Rhaenyra, Baela, or Daemon must be explicitly tied to Jace''s death. A casual mention of Jace without present-tense consequence does not count.', 'Jace Guilt', 'false', 'jace_guilt', 'Jace Guilt', 'black_court', '55', 'toss_up', 'A current decision or confrontation involving Rhaena, Rhaenyra, Baela, or Daemon must be explicitly tied to Jace''s death. A casual mention of Jace without present-tense consequence does not count.', 'Rewards the finale for paying off one of the season''s biggest emotional losses instead of simply name-checking it.', '{jace,rhaena,rhaenyra,callback}', 'callback'),
  ('21', 'Daemon must do something clearly motivated by protecting, comforting, or loving Baela or Rhaena as their father. Tactical cooperation does not count unless the parental motivation is explicit or unmistakable.', 'Daemon Daddy', 'false', 'daemon_daddy', 'Daemon Daddy', 'black_court', '50', 'toss_up', 'Daemon must do something clearly motivated by protecting, comforting, or loving Baela or Rhaena as their father. Tactical cooperation does not count unless the parental motivation is explicit or unmistakable.', 'A rare warm Daemon square and a continuation of the season''s more paternal turn with Rhaena.', '{daemon,rhaena,baela}', 'audience-love'),
  ('22', 'Daemon must deliberately disobey, circumvent, or materially contradict Rhaenyra. An argument does not count if he ultimately does exactly what she orders.', 'Daemon Defies', 'false', 'daemon_defies', 'Daemon Defies', 'black_court', '55', 'toss_up', 'Daemon must deliberately disobey, circumvent, or materially contradict Rhaenyra. An argument does not count if he ultimately does exactly what she orders.', 'Their fractured trust has been one of the season''s persistent Black-side tensions.', '{daemon,rhaenyra,blacks}', 'conflict'),
  ('23', 'A named character must directly tell Rhaenyra that one of her choices has been foolish, damaging, cruel, or politically disastrous. Polite advice or mild disagreement does not count; it has to sting.', 'Rhaenyra Dragged', 'false', 'rhaenyra_dragged', 'Rhaenyra Dragged', 'black_court', '65', 'likely', 'A named character must directly tell Rhaenyra that one of her choices has been foolish, damaging, cruel, or politically disastrous. Polite advice or mild disagreement does not count; it has to sting.', 'Turns a major audience frustration with her rule into a cheerable square.', '{rhaenyra,kings_landing,blacks}', 'audience-hate'),
  ('24', 'Rhaenyra and Mysaria must share an unmistakably romantic or sexual continuation of their relationship, such as a kiss, sexual contact, a clear proposition, or waking together with explicit implication. Ordinary confidante intimacy does not count.', 'Sapphic Spark', 'false', 'sapphic_spark', 'Sapphic Spark', 'black_court', '50', 'toss_up', 'Rhaenyra and Mysaria must share an unmistakably romantic or sexual continuation of their relationship, such as a kiss, sexual contact, a clear proposition, or waking together with explicit implication. Ordinary confidante intimacy does not count.', 'A fun, fandom-aware square that gives viewers something to root for beyond military outcomes.', '{rhaenyra,mysaria,romance}', 'audience-love'),
  ('25', 'A named character must directly challenge, expose, insult, or criticize Mysaria or her influence over Rhaenyra. Generic complaints about Rhaenyra''s government do not count.', 'Mysaria Roasted', 'false', 'mysaria_roasted', 'Mysaria Roasted', 'black_court', '35', 'long_shot', 'A named character must directly challenge, expose, insult, or criticize Mysaria or her influence over Rhaenyra. Generic complaints about Rhaenyra''s government do not count.', 'A payoff square for viewers frustrated by Mysaria''s influence and screen time.', '{mysaria,rhaenyra,blacks}', 'audience-hate'),
  ('26', 'Questions about bastardy, dragonseeds, legitimacy, or resentment of Rhaenyra''s elevation of lowborn riders must materially affect a conversation or decision. A random use of the word “bastard” as an insult does not count.', 'Bastard Problem', 'false', 'bastard_problem', 'Bastard Problem', 'black_court', '45', 'toss_up', 'Questions about bastardy, dragonseeds, legitimacy, or resentment of Rhaenyra''s elevation of lowborn riders must materially affect a conversation or decision. A random use of the word “bastard” as an insult does not count.', 'Keeps one of the season''s class-and-legitimacy tensions alive without requiring a specific book outcome.', '{dragonseeds,rhaenyra,legitimacy}', 'callback'),
  ('27', 'The crown''s missing money or lack of funds must create a concrete problem or constrain a decision. A generic statement that war is expensive does not count.', 'Broke Queen', 'false', 'broke_queen', 'Broke Queen', 'black_court', '45', 'toss_up', 'The crown''s missing money or lack of funds must create a concrete problem or constrain a decision. A generic statement that war is expensive does not count.', 'A season-wide callback to the less glamorous problem Rhaenyra inherited after taking King''s Landing: ruling costs money.', '{rhaenyra,treasury,kings_landing}', 'callback'),
  ('28', 'Rhaena must visibly cry or emotionally break down on screen. Looking sad, wet-eyed, or miserable without an actual breakdown does not count.', 'Rhaena Cries', 'false', 'rhaena_cries', 'Rhaena Cries', 'black_court', '55', 'toss_up', 'Rhaena must visibly cry or emotionally break down on screen. Looking sad, wet-eyed, or miserable without an actual breakdown does not count.', 'Simple, petty, highly judgeable, and exactly the kind of square that makes a watch party laugh.', '{rhaena}', 'audience-hate'),
  ('29', 'Rhaena must explicitly apologize to another character for Sheepstealer, Jace, the Gullet, or her actions this season. Regretful expressions or self-blame without an actual apology do not count.', 'Rhaena Says Sorry', 'false', 'rhaena_says_sorry', 'Rhaena Says Sorry', 'black_court', '25', 'long_shot', 'Rhaena must explicitly apologize to another character for Sheepstealer, Jace, the Gullet, or her actions this season. Regretful expressions or self-blame without an actual apology do not count.', 'A long-shot accountability square for viewers waiting for her choices to be addressed.', '{rhaena,jace,sheepstealer}', 'callback'),
  ('3', 'A dragonrider must involuntarily fall, be thrown, or be knocked from their dragon. A planned jump, ordinary dismount, or climbing off after landing does not count.', 'Rider Falls', 'false', 'rider_falls', 'Rider Falls', 'dragons', '45', 'toss_up', 'A dragonrider must involuntarily fall, be thrown, or be knocked from their dragon. A planned jump, ordinary dismount, or climbing off after landing does not count.', 'A classic bingo shock square: specific, visual, and immediately yell-worthy.', '{dragons,riders,combat}', 'spectacle'),
  ('30', 'The Iron Throne must visibly cut, wound, or draw blood from someone during the finale. A character merely touching, sitting on, or talking about the throne does not count.', 'Throne Bites Back', 'false', 'iron_throne_bites', 'Throne Bites Back', 'black_court', '15', 'chaos', 'The Iron Throne must visibly cut, wound, or draw blood from someone during the finale. A character merely touching, sitting on, or talking about the throne does not count.', 'A pure lore-flavored chaos square with a wonderfully objective visual trigger.', '{iron_throne,rhaenyra,kings_landing}', 'chaos'),
  ('31', 'Aegon must deliver an unmistakably sarcastic, cutting, morbidly funny, or self-aware line. Someone else joking about Aegon does not count.', 'Aegon Sass', 'false', 'aegon_sass', 'Aegon Sass', 'greens_harrenhal', '70', 'likely', 'Aegon must deliver an unmistakably sarcastic, cutting, morbidly funny, or self-aware line. Someone else joking about Aegon does not count.', 'His dark humor has become one of the most entertaining parts of his wounded road-story persona.', '{aegon,greens}', 'audience-love'),
  ('32', 'Aegon must actively behave like a claimant again by issuing an order, demanding allegiance, rallying support, or publicly asserting royal authority. Simply surviving with Sunfyre does not count.', 'Aegon Goes King', 'false', 'aegon_goes_king', 'Aegon Goes King', 'greens_harrenhal', '55', 'toss_up', 'Aegon must actively behave like a claimant again by issuing an order, demanding allegiance, rallying support, or publicly asserting royal authority. Simply surviving with Sunfyre does not count.', 'Tests whether the late-season Sunfyre reunion translates into actual political swagger.', '{aegon,sunfyre,greens}', 'character-payoff'),
  ('33', 'Larys must manipulate, betray, blackmail, strategically lie to, or quietly use somebody. His full scheme does not have to be revealed; unmistakable Larys behavior is enough.', 'Larys Being Larys', 'false', 'larys_being_larys', 'Larys Being Larys', 'greens_harrenhal', '65', 'likely', 'Larys must manipulate, betray, blackmail, strategically lie to, or quietly use somebody. His full scheme does not have to be revealed; unmistakable Larys behavior is enough.', 'A broad but character-specific square that feels like betting on gravity.', '{larys,aegon,greens}', 'character-comedy'),
  ('34', 'Tyland must do something unexpectedly brave, competent, loyal, funny, or consequential. Routine participation beside Aegon does not count.', 'Tyland Surprise', 'false', 'tyland_surprise', 'Tyland Surprise', 'greens_harrenhal', '45', 'toss_up', 'Tyland must do something unexpectedly brave, competent, loyal, funny, or consequential. Routine participation beside Aegon does not count.', 'Gives a supporting character a chance to become the night''s random MVP.', '{tyland,aegon,greens}', 'wildcard'),
  ('35', 'Aemond must clearly regain consciousness and become mentally responsive after Alicent''s poisoning. A dream or vision featuring Aemond does not count if the real Aemond remains unconscious.', 'Aemond Wakes', 'false', 'aemond_wakes', 'Aemond Wakes', 'greens_harrenhal', '70', 'likely', 'Aemond must clearly regain consciousness and become mentally responsive after Alicent''s poisoning. A dream or vision featuring Aemond does not count if the real Aemond remains unconscious.', 'Directly resolves the episode-7 cliffhanger without predicting what he does afterward.', '{aemond,alicent,harrenhal}', 'plot-payoff'),
  ('36', 'Aemond must again emotionally, sexually, hallucinatorily, or psychologically fixate on Alicent. A purely strategic reference to his mother does not count unless the scene clearly carries the season''s loaded maternal obsession.', 'Mommy Issues', 'false', 'mommy_issues', 'Mommy Issues', 'greens_harrenhal', '50', 'toss_up', 'Aemond must again emotionally, sexually, hallucinatorily, or psychologically fixate on Alicent. A purely strategic reference to his mother does not count unless the scene clearly carries the season''s loaded maternal obsession.', 'The most meme-ready distillation of Aemond''s increasingly bizarre season arc.', '{aemond,alicent,alys}', 'character-comedy'),
  ('37', 'Alys must do something presented as supernatural, prophetic, impossible, or deliberately witch-like. Ordinary medicine, herb lore, or vague creepiness does not count on its own.', 'Alys Witchcraft', 'false', 'alys_witchcraft', 'Alys Witchcraft', 'greens_harrenhal', '50', 'toss_up', 'Alys must do something presented as supernatural, prophetic, impossible, or deliberately witch-like. Ordinary medicine, herb lore, or vague creepiness does not count on its own.', 'Lets the Harrenhal story earn its weirdness instead of just talking mysteriously.', '{alys,aemond,harrenhal}', 'weird'),
  ('38', 'A present-day Harrenhal scene must contain a vision, hallucination, supernatural event, eerie omen, or similarly inexplicable occurrence. Ordinary dialogue inside Harrenhal does not count.', 'Harrenhal Gets Weird', 'false', 'harrenhal_gets_weird', 'Harrenhal Gets Weird', 'greens_harrenhal', '65', 'likely', 'A present-day Harrenhal scene must contain a vision, hallucination, supernatural event, eerie omen, or similarly inexplicable occurrence. Ordinary dialogue inside Harrenhal does not count.', 'An easy-to-understand running gag after two seasons of Harrenhal refusing to behave like normal real estate.', '{harrenhal,visions,alys,aemond}', 'weird'),
  ('39', 'Alicent must explicitly regret poisoning Aemond or actively attempt to reverse or mitigate what she did. Merely looking distressed or conflicted does not count.', 'Alicent Regrets It', 'false', 'alicent_regrets_it', 'Alicent Regrets It', 'greens_harrenhal', '35', 'long_shot', 'Alicent must explicitly regret poisoning Aemond or actively attempt to reverse or mitigate what she did. Merely looking distressed or conflicted does not count.', 'A character-payoff square built around one of the penultimate episode''s biggest moral choices.', '{alicent,aemond}', 'character-payoff'),
  ('4', 'A dragon must attack, burn, injure, or kill someone fighting on its rider''s own side. An accidental near-miss does not count unless someone or something allied is actually hit.', 'Friendly Fire', 'false', 'friendly_fire', 'Friendly Fire', 'dragons', '35', 'long_shot', 'A dragon must attack, burn, injure, or kill someone fighting on its rider''s own side. An accidental near-miss does not count unless someone or something allied is actually hit.', 'Calls back to the season''s repeated theme that dragons are not perfectly controllable weapons.', '{dragons,control,callback}', 'callback'),
  ('40', 'Helaena must say something clearly prophetic, ominous, bizarre, or difficult for the other characters to understand. Ordinary dialogue about her family, captivity, or pregnancy does not count.', 'Helaena Says What', 'false', 'helaena_says_what', 'Helaena Says What', 'greens_harrenhal', '75', 'likely', 'Helaena must say something clearly prophetic, ominous, bizarre, or difficult for the other characters to understand. Ordinary dialogue about her family, captivity, or pregnancy does not count.', 'One of the best recurring bingo beats because her visions are both plot-relevant and inherently weird.', '{helaena,visions,dreamfyre}', 'audience-love'),
  ('41', 'Helaena must make a consequential decision for herself rather than simply comply with someone else''s plan. A refusal counts if it changes what happens.', 'Helaena Chooses', 'false', 'helaena_chooses', 'Helaena Chooses', 'greens_harrenhal', '50', 'toss_up', 'Helaena must make a consequential decision for herself rather than simply comply with someone else''s plan. A refusal counts if it changes what happens.', 'Her season arc has increasingly been about asserting agency while other people try to use her.', '{helaena,alicent,greens}', 'character-payoff'),
  ('42', 'A named character must actively defend, rescue, hide, advocate for, or otherwise protect Helaena. Feeling sorry for her or offering comfort without action does not count.', 'Protect Helaena', 'false', 'protect_helaena', 'Protect Helaena', 'greens_harrenhal', '45', 'toss_up', 'A named character must actively defend, rescue, hide, advocate for, or otherwise protect Helaena. Feeling sorry for her or offering comfort without action does not count.', 'A fandom-friendly rooting square for one of the season''s most protected-by-the-audience characters.', '{helaena,greens}', 'audience-love'),
  ('43', 'Aemond must die from Alicent''s poisoning, or another character must definitively state that the poison killed him. Remaining unconscious, sick, or in danger does not count.', 'Poison Works', 'false', 'poison_works', 'Poison Works', 'greens_harrenhal', '25', 'long_shot', 'Aemond must die from Alicent''s poisoning, or another character must definitively state that the poison killed him. Remaining unconscious, sick, or in danger does not count.', 'A high-stakes long shot tied directly to episode 7''s cliffhanger.', '{aemond,alicent,poison}', 'plot-payoff'),
  ('44', 'Helaena must physically ride Dreamfyre in the present timeline, not merely in a dream, prophecy, memory, or vision. Dreamfyre appearing without Helaena mounted does not count.', 'Dreamfyre Takes Flight', 'false', 'dreamfyre_real_ride', 'Dreamfyre Takes Flight', 'greens_harrenhal', '18', 'chaos', 'Helaena must physically ride Dreamfyre in the present timeline, not merely in a dream, prophecy, memory, or vision. Dreamfyre appearing without Helaena mounted does not count.', 'A deliberately hard chaos square after episode 7 teased the image in a vision.', '{helaena,dreamfyre,dragonrider}', 'chaos'),
  ('45', 'Aemond must definitively die during the finale from any cause. Severe injury, collapse, disappearance, or an ambiguous apparent death does not count.', 'Aemond Dies', 'false', 'aemond_dies', 'Aemond Dies', 'greens_harrenhal', '15', 'chaos', 'Aemond must definitively die during the finale from any cause. Severe injury, collapse, disappearance, or an ambiguous apparent death does not count.', 'A true jackpot square that makes the poison cliffhanger matter without assuming its outcome.', '{aemond,death}', 'chaos'),
  ('46', 'Ormund must suffer a real humiliation, defeat, injury, rejection, or meaningful loss of control. Someone merely disagreeing with him is not enough.', 'Ormund Humbled', 'false', 'ormund_humbled', 'Ormund Humbled', 'tumbleton', '50', 'toss_up', 'Ormund must suffer a real humiliation, defeat, injury, rejection, or meaningful loss of control. Someone merely disagreeing with him is not enough.', 'A pure audience-payoff square for a character people enjoy hating.', '{ormund,hightower,tumbleton}', 'audience-hate'),
  ('47', 'Daeron must openly refuse, undermine, or counter something Ormund wants him to do. Quiet discomfort or private disagreement does not count unless Daeron acts on it.', 'Daeron Defies', 'false', 'daeron_defies', 'Daeron Defies', 'tumbleton', '65', 'likely', 'Daeron must openly refuse, undermine, or counter something Ormund wants him to do. Quiet discomfort or private disagreement does not count unless Daeron acts on it.', 'The Daeron–Ormund power struggle has become one of the season''s clearest internal Green conflicts.', '{daeron,ormund,tumbleton}', 'audience-love'),
  ('48', 'Ulf must be punched, shoved, thrown down, burned, struck, or otherwise physically punished. Verbal abuse alone does not count.', 'Ulf Gets Smacked', 'false', 'ulf_gets_smacked', 'Ulf Gets Smacked', 'tumbleton', '45', 'toss_up', 'Ulf must be punched, shoved, thrown down, burned, struck, or otherwise physically punished. Verbal abuse alone does not count.', 'Simple, mean, and extremely easy to adjudicate.', '{ulf,dragonseeds}', 'audience-hate'),
  ('49', 'Someone aligned with Rhaenyra must discover or directly witness Ulf''s secret cooperation with Ormund. Private Green-side scheming does not count until the betrayed side knows.', 'Ulf Exposed', 'false', 'ulf_exposed', 'Ulf Exposed', 'tumbleton', '55', 'toss_up', 'Someone aligned with Rhaenyra must discover or directly witness Ulf''s secret cooperation with Ormund. Private Green-side scheming does not count until the betrayed side knows.', 'A payoff to one of episode 7''s most explicit unresolved betrayal setups.', '{ulf,ormund,rhaenyra}', 'plot-payoff'),
  ('5', 'A dragon must visibly resist, ignore, or refuse what its rider is trying to make it do. General difficulty riding or mounting does not count unless the dragon clearly asserts its own will.', 'Dragon Says Nope', 'false', 'dragon_says_nope', 'Dragon Says Nope', 'dragons', '45', 'toss_up', 'A dragon must visibly resist, ignore, or refuse what its rider is trying to make it do. General difficulty riding or mounting does not count unless the dragon clearly asserts its own will.', 'Funny because the dragons increasingly seem to have better judgment than their riders.', '{dragons,control}', 'character-comedy'),
  ('50', 'Hugh must make a clear, consequential decision about his loyalties, Kat, or his role as a dragonrider and then act on it. Hesitation, complaining, or merely receiving an offer does not count.', 'Hugh Chooses', 'false', 'hugh_chooses', 'Hugh Chooses', 'tumbleton', '50', 'toss_up', 'Hugh must make a clear, consequential decision about his loyalties, Kat, or his role as a dragonrider and then act on it. Hesitation, complaining, or merely receiving an offer does not count.', 'Keeps Hugh suspenseful without importing any unaired book outcome.', '{hugh,kat,dragonseeds}', 'plot-payoff'),
  ('51', 'Kat must escape, be rescued, or otherwise be removed from immediate danger in Tumbleton. Someone offering to help her without successfully doing so does not count.', 'Kat Gets Out', 'false', 'kat_gets_out', 'Kat Gets Out', 'tumbleton', '30', 'long_shot', 'Kat must escape, be rescued, or otherwise be removed from immediate danger in Tumbleton. Someone offering to help her without successfully doing so does not count.', 'A smaller human-scale rooting interest amid all the dragons and armies.', '{kat,hugh,tumbleton}', 'audience-love'),
  ('52', 'Corlys must escape, be rescued, or be intentionally released from captivity. An attempted rescue does not count unless the Sea Snake actually becomes free.', 'Corlys Freed', 'false', 'corlys_freed', 'Corlys Freed', 'tumbleton', '35', 'long_shot', 'Corlys must escape, be rescued, or be intentionally released from captivity. An attempted rescue does not count unless the Sea Snake actually becomes free.', 'A clean payoff to his late-season capture and a good medium-hard square.', '{corlys,velaryon,tumbleton}', 'plot-payoff'),
  ('53', 'Alyn must disobey orders or take an unauthorized serious risk involving Corlys, Baela, the Velaryons, or the war. Normal participation in battle does not count.', 'Alyn Goes Rogue', 'false', 'alyn_goes_rogue', 'Alyn Goes Rogue', 'tumbleton', '30', 'long_shot', 'Alyn must disobey orders or take an unauthorized serious risk involving Corlys, Baela, the Velaryons, or the war. Normal participation in battle does not count.', 'Makes Corlys''s capture personal and gives Alyn a chance to drive plot instead of just react.', '{alyn,corlys,velaryon}', 'character-payoff'),
  ('54', 'Roddy Dustin, Oscar Tully, Black Aly, or their allied northern/river forces must launch or join a meaningful attack. Merely showing the army marching, camping, or discussing battle plans does not count.', 'Northmen Charge', 'false', 'northmen_charge', 'Northmen Charge', 'tumbleton', '55', 'toss_up', 'Roddy Dustin, Oscar Tully, Black Aly, or their allied northern/river forces must launch or join a meaningful attack. Merely showing the army marching, camping, or discussing battle plans does not count.', 'Extends the Butcher''s Ball ground-war momentum into a concrete, cheerable event.', '{northmen,riverlands,tumbleton}', 'spectacle'),
  ('55', 'Criston''s death or the consequences of his failed campaign must meaningfully affect current dialogue or a decision. Merely listing him among casualties does not count.', 'Criston Callback', 'false', 'criston_callback', 'Criston Callback', 'tumbleton', '30', 'long_shot', 'Criston''s death or the consequences of his failed campaign must meaningfully affect current dialogue or a decision. Merely listing him among casualties does not count.', 'A callback that asks the finale to acknowledge a major season-long character rather than repeat an old scene.', '{criston,greens,callback}', 'callback'),
  ('56', 'A substantial organized battle must begin at or immediately around Tumbleton. A tiny skirmish does not count; armies, dragons, or clearly organized military forces must genuinely engage.', 'Tumbleton Battle', 'false', 'tumbleton_battle', 'Tumbleton Battle', 'tumbleton', '65', 'likely', 'A substantial organized battle must begin at or immediately around Tumbleton. A tiny skirmish does not count; armies, dragons, or clearly organized military forces must genuinely engage.', 'One of the season''s most visibly converging military threads and a natural finale anchor.', '{tumbleton,battle,hightower}', 'spectacle'),
  ('57', 'Someone must explicitly threaten to harm, kill, mutilate, or otherwise use a captive to force another character''s behavior. Simply mentioning that a person is imprisoned does not count.', 'Hostage Threat', 'false', 'hostage_threat', 'Hostage Threat', 'tumbleton', '40', 'toss_up', 'Someone must explicitly threaten to harm, kill, mutilate, or otherwise use a captive to force another character''s behavior. Simply mentioning that a person is imprisoned does not count.', 'Corlys''s captivity creates a clean setup for this without making it inevitable.', '{corlys,hostage,tumbleton}', 'conflict'),
  ('58', 'Corlys must lose another finger, limb, eye, or other body part during the finale. Threats, off-screen torture without visible loss, or injuries that leave everything attached do not count.', 'More Corlys Parts', 'false', 'corlys_loses_more', 'More Corlys Parts', 'tumbleton', '18', 'chaos', 'Corlys must lose another finger, limb, eye, or other body part during the finale. Threats, off-screen torture without visible loss, or injuries that leave everything attached do not count.', 'A nasty little chaos square based on how badly his captivity has already gone.', '{corlys,gore,captivity}', 'chaos'),
  ('59', 'Ulf must be formally granted, publicly promised, or seriously claim a new noble title, lordship, castle, or landholding. Empty flattery or joking titles do not count.', 'Ulf Gets a Title', 'false', 'ulf_changes_title', 'Ulf Gets a Title', 'tumbleton', '40', 'toss_up', 'Ulf must be formally granted, publicly promised, or seriously claim a new noble title, lordship, castle, or landholding. Empty flattery or joking titles do not count.', 'Direct payoff to Ormund using status and social recognition to tempt him.', '{ulf,ormund,status}', 'plot-payoff'),
  ('6', 'A dragon must visibly bite, eat, or swallow a human, animal, or substantial piece of flesh. Burning someone does not count unless the dragon actually takes a bite.', 'Dragon Snack', 'false', 'dragon_snack', 'Dragon Snack', 'dragons', '30', 'long_shot', 'A dragon must visibly bite, eat, or swallow a human, animal, or substantial piece of flesh. Burning someone does not count unless the dragon actually takes a bite.', 'Gross, unmistakable, and much more fun than a generic battle square.', '{dragons,gore}', 'chaotic'),
  ('60', 'Daeron and Tessarion must share a clearly affectionate, protective, or emotionally meaningful interaction. Routine mounting or battle commands do not count without a visible bond.', 'Tessarion Love', 'false', 'daeron_tessarion_love', 'Tessarion Love', 'tumbleton', '45', 'toss_up', 'Daeron and Tessarion must share a clearly affectionate, protective, or emotionally meaningful interaction. Routine mounting or battle commands do not count without a visible bond.', 'Mirrors the audience affection for Aegon/Sunfyre and lets Daeron''s dragon relationship get its own rooting square.', '{daeron,tessarion,dragon-bond}', 'audience-love'),
  ('61', 'Jace''s death must directly motivate a present-tense decision, confrontation, threat, or emotional break. A casual mention of his name or memorial image does not count.', 'Dead Son Callback', 'false', 'dead_son_callback', 'Dead Son Callback', 'callbacks_chaos', '55', 'toss_up', 'Jace''s death must directly motivate a present-tense decision, confrontation, threat, or emotional break. A casual mention of his name or memorial image does not count.', 'A season-wide callback that only hits if the loss still matters to what people do now.', '{jace,callback,grief}', 'callback'),
  ('62', 'Otto''s execution, advice, political legacy, or absence must materially influence a current decision or confrontation. A casual historical mention does not count.', 'Otto''s Shadow', 'false', 'otto_shadow', 'Otto''s Shadow', 'callbacks_chaos', '25', 'long_shot', 'Otto''s execution, advice, political legacy, or absence must materially influence a current decision or confrontation. A casual historical mention does not count.', 'A long-shot callback to one of the season''s early turning points.', '{otto,alicent,rhaenyra,callback}', 'callback'),
  ('63', 'Someone must use a fake person, false body, staged evidence, false identity, or deliberate decoy as part of an active plan. A lie told in conversation without a physical or identity-based deception does not count.', 'Decoy Trick', 'false', 'decoy_trick', 'Decoy Trick', 'callbacks_chaos', '30', 'long_shot', 'Someone must use a fake person, false body, staged evidence, false identity, or deliberate decoy as part of an active plan. A lie told in conversation without a physical or identity-based deception does not count.', 'Echoes the season''s repeated use of deception and fake-outs without requiring any one past scene to be repeated.', '{deception,callback}', 'callback'),
  ('64', 'A scene must initially appear to be happening for real and then be revealed as a dream, hallucination, prophecy, or vision. A sequence that is obviously surreal from the first shot does not count.', 'Vision Fakeout', 'false', 'vision_fakeout', 'Vision Fakeout', 'callbacks_chaos', '45', 'toss_up', 'A scene must initially appear to be happening for real and then be revealed as a dream, hallucination, prophecy, or vision. A sequence that is obviously surreal from the first shot does not count.', 'A perfect bingo mechanic for a season that keeps weaponizing subjective reality.', '{visions,harrenhal,helaena}', 'weird'),
  ('65', 'A living rat must be clearly visible on screen. Dead rats, rat-shaped decorations, or dialogue about rats do not count.', 'Rat Cameo', 'false', 'rat_cameo', 'Rat Cameo', 'callbacks_chaos', '10', 'chaos', 'A living rat must be clearly visible on screen. Dead rats, rat-shaped decorations, or dialogue about rats do not count.', 'Tiny, objective, ridiculous, and therefore elite bingo material.', '{rat,kings_landing}', 'chaos'),
  ('66', 'Wine or another drink must become relevant to poisoning, deception, danger, or a consequential decision. Someone simply drinking while brooding does not count.', 'Wine Suspicious', 'false', 'wine_suspicious', 'Wine Suspicious', 'callbacks_chaos', '40', 'toss_up', 'Wine or another drink must become relevant to poisoning, deception, danger, or a consequential decision. Someone simply drinking while brooding does not count.', 'A classic Westerosi danger signal and a playful echo of this season''s poisoning thread.', '{wine,poison,deception}', 'callback'),
  ('67', 'A major character must spend several silent seconds staring dramatically through a window, over a balcony, or into the distance. Walking past a window during dialogue does not count.', 'Brooding Window', 'false', 'brooding_window', 'Brooding Window', 'callbacks_chaos', '75', 'likely', 'A major character must spend several silent seconds staring dramatically through a window, over a balcony, or into the distance. Walking past a window during dialogue does not count.', 'The premium-HBO free-space-that-isn''t-a-free-space.', '{visual-trope,brooding}', 'trope'),
  ('68', 'A human head must become fully detached from its body during the episode. Sword, axe, dragon, accident, or another gruesome method all count.', 'Head Comes Off', 'false', 'head_comes_off', 'Head Comes Off', 'callbacks_chaos', '40', 'toss_up', 'A human head must become fully detached from its body during the episode. Sword, axe, dragon, accident, or another gruesome method all count.', 'Specific gore is more fun than generic ''battle happens'' predictions.', '{gore,death}', 'chaotic'),
  ('69', 'A clearly visible person must actually catch fire. Being near dragonfire, smoke, or an explosion without visibly burning does not count.', 'Someone Burns', 'false', 'someone_burns', 'Someone Burns', 'callbacks_chaos', '70', 'likely', 'A clearly visible person must actually catch fire. Being near dragonfire, smoke, or an explosion without visibly burning does not count.', 'Very plausible in a dragon-war finale and instantly judgeable.', '{dragonfire,gore,combat}', 'spectacle'),
  ('7', 'A dragon must collide hard with the ground, a building, ship, another dragon, or another major object. A rough but intentional landing does not count.', 'Dragon Crash', 'false', 'dragon_crash', 'Dragon Crash', 'dragons', '40', 'toss_up', 'A dragon must collide hard with the ground, a building, ship, another dragon, or another major object. A rough but intentional landing does not count.', 'A visual stunt square that can hit during almost any dragon sequence.', '{dragons,combat}', 'spectacle'),
  ('70', 'The camera must linger on an unusually gruesome wound, corpse, exposed anatomy, mutilation, or dismemberment. Ordinary battle blood is not enough.', 'Gratuitous Gore', 'false', 'gratuitous_gore', 'Gratuitous Gore', 'callbacks_chaos', '70', 'likely', 'The camera must linger on an unusually gruesome wound, corpse, exposed anatomy, mutilation, or dismemberment. Ordinary battle blood is not enough.', 'A classic House of the Dragon reaction square that does not depend on any one storyline.', '{gore,visual-trope}', 'trope'),
  ('71', 'The episode must depict unmistakable sexual activity between characters. Kissing, flirtation, post-sex conversation, or sex that happens entirely off-screen does not count.', 'Sex Scene', 'false', 'sex_scene', 'Sex Scene', 'callbacks_chaos', '30', 'long_shot', 'The episode must depict unmistakable sexual activity between characters. Kissing, flirtation, post-sex conversation, or sex that happens entirely off-screen does not count.', 'Adds a very different kind of suspense to a board otherwise full of murder and dragons.', '{sex,romance}', 'chaotic'),
  ('72', 'Someone must discover or use a concealed door, hidden corridor, tunnel, or escape route. An ordinary dungeon corridor or back staircase does not count.', 'Secret Passage', 'false', 'secret_passage', 'Secret Passage', 'callbacks_chaos', '25', 'long_shot', 'Someone must discover or use a concealed door, hidden corridor, tunnel, or escape route. An ordinary dungeon corridor or back staircase does not count.', 'Classic King''s Landing nonsense and a useful low-probability board differentiator.', '{escape,kings_landing,deception}', 'trope'),
  ('73', 'A raven-delivered message must arrive with information that significantly worsens someone''s situation or forces a change of plan. Routine correspondence or a harmless update does not count.', 'Raven Ruins Everything', 'false', 'raven_ruins_everything', 'Raven Ruins Everything', 'callbacks_chaos', '45', 'toss_up', 'A raven-delivered message must arrive with information that significantly worsens someone''s situation or forces a change of plan. Routine correspondence or a harmless update does not count.', 'Turns exposition into a fun event: bad news by bird.', '{raven,message,politics}', 'trope'),
  ('74', 'Someone must deliberately kneel as an act of allegiance, surrender, petition, forgiveness, or submission. Falling because of injury, exhaustion, or poisoning does not count.', 'Someone Kneels', 'false', 'someone_kneels', 'Someone Kneels', 'callbacks_chaos', '65', 'likely', 'Someone must deliberately kneel as an act of allegiance, surrender, petition, forgiveness, or submission. Falling because of injury, exhaustion, or poisoning does not count.', 'Very Westerosi, extremely visible, and usable across almost every storyline.', '{allegiance,politics}', 'trope'),
  ('75', 'Any named character must definitively die during the episode. Background soldiers, civilians, horses, nameless guards, and ambiguous apparent deaths do not count.', 'Named Death', 'false', 'named_death', 'Named Death', 'callbacks_chaos', '80', 'likely', 'Any named character must definitively die during the episode. Background soldiers, civilians, horses, nameless guards, and ambiguous apparent deaths do not count.', 'The broadest high-probability anchor, useful for balancing difficult boards.', '{death,named-character}', 'anchor'),
  ('8', 'A character must audibly say “Dracarys” as a command. Dragonfire without the spoken command does not satisfy the square.', 'Dracarys Spoken', 'false', 'dracarys_spoken', 'Dracarys Spoken', 'dragons', '55', 'toss_up', 'A character must audibly say “Dracarys” as a command. Dragonfire without the spoken command does not satisfy the square.', 'Simple, iconic, and satisfying to mark the instant it happens.', '{dragons,targaryen,dialogue}', 'catchphrase'),
  ('9', 'Aegon and Sunfyre must share a clearly affectionate or emotionally meaningful interaction. Merely appearing together, mounting, or fighting side by side does not count without an obvious emotional beat.', 'Sunfyre Love', 'false', 'sunfyre_love', 'Sunfyre Love', 'dragons', '50', 'toss_up', 'Aegon and Sunfyre must share a clearly affectionate or emotionally meaningful interaction. Merely appearing together, mounting, or fighting side by side does not count without an obvious emotional beat.', 'The Aegon–Sunfyre reunion was one of the most audience-loved late-season moments, so this gives viewers something to actively root for.', '{aegon,sunfyre,greens}', 'audience-love')
insert into public.signature_beats ("id", "entity_id", "name", "trigger_text", "odds", "points", "pitch", "partner_entity_id") values
  ('1', 'aa56f006-abe3-5047-4893-40d08cac7dda', 'Caraxes Sortie', 'Daemon mounts Caraxes and deliberately enters an active combat, pursuit, or interception scene.', 'Likely', '20', 'The Blood Wyrm is still Daemon''s most reliable argument.', NULL),
  ('10', '9ac3581a-94f5-9fc1-d003-bbc4ed9971e5', 'Punishes Daemon', 'Rhaenyra orders Daemon confined, stripped of authority, arrested, or otherwise formally punished.', 'Long shot', '35', 'The marriage becomes a constitutional crisis.', NULL),
  ('100', '32f57c47-f49c-4003-3748-c120aae7c45a', 'Criston Tribute', 'Gwayne explicitly honors, mourns, defends, or invokes Criston Cole''s memory in a present-tense decision.', 'Coin flip', '25', 'A dead commander still has a hold on him.', NULL),
  ('101', '6d5fc989-7205-b24a-2231-ff3297c0749e', 'Guards Corlys', 'Jon is visibly assigned to, escorting, or personally guarding Corlys as a captive.', 'Likely', '20', 'Even a minor villain needs a floor, and Corlys is his ticket.', NULL),
  ('102', '6d5fc989-7205-b24a-2231-ff3297c0749e', 'Hurts Corlys', 'Jon personally wounds, mutilates, or tortures Corlys on screen.', 'Coin flip', '25', 'The nasty branch: the hostage situation gets worse.', NULL),
  ('103', '6d5fc989-7205-b24a-2231-ff3297c0749e', 'Frees Corlys', 'Jon deliberately releases or helps Corlys escape against Ormund''s interests.', 'Wild', '45', 'The wildest redemption swing on the character board.', NULL),
  ('104', '6d5fc989-7205-b24a-2231-ff3297c0749e', 'Obeys Ormund', 'Jon carries out a consequential direct order from Ormund in the finale.', 'Likely', '20', 'The loyal henchman stays useful.', NULL),
  ('105', '6d5fc989-7205-b24a-2231-ff3297c0749e', 'Refuses Ormund', 'Jon openly refuses a direct order from Ormund or abandons an assigned Hightower task.', 'Likely', '20', 'Or the hired sword remembers he is not actually a Hightower.', NULL),
  ('106', 'b3b10757-625e-0013-92ab-7a083d26ce7d', 'Rejects His Captor', 'Corlys directly refuses a demand, bargain, oath, or threat made by Ormund or Jon Roxton.', 'Likely', '20', 'Missing finger, intact spine.', NULL),
  ('107', 'b3b10757-625e-0013-92ab-7a083d26ce7d', 'Escape Attempt', 'Corlys personally attempts to escape his captivity, whether or not the attempt succeeds.', 'Coin flip', '25', 'The Sea Snake tries to solve his own problem.', NULL),
  ('108', 'b3b10757-625e-0013-92ab-7a083d26ce7d', 'Takes a Deal', 'Corlys knowingly accepts a bargain or concession demanded by his captors in exchange for safety or another person''s protection.', 'Coin flip', '25', 'Survival requires swallowing his pride.', NULL),
  ('109', 'b3b10757-625e-0013-92ab-7a083d26ce7d', 'Reconciles With Alyn', 'Corlys explicitly apologizes to Alyn or the two reach a clear father-son reconciliation.', 'Coin flip', '25', 'The emotional rescue payoff.', NULL),
  ('11', '9ac3581a-94f5-9fc1-d003-bbc4ed9971e5', 'Sapphic Spark', 'Rhaenyra and Mysaria share an unmistakably romantic or sexual interaction in the present timeline.', 'Coin flip', '25', 'The politics stop for one very specific kind of diplomacy.', NULL),
  ('110', 'b3b10757-625e-0013-92ab-7a083d26ce7d', 'Clashes With Alyn', 'After reuniting or communicating, Corlys and Alyn directly argue about fatherhood, legitimacy, or Corlys''s past treatment of his sons.', 'Coin flip', '25', 'Rescue immediately becomes family therapy.', NULL),
  ('111', 'b3b10757-625e-0013-92ab-7a083d26ce7d', 'Names His Sons', 'Corlys publicly or directly acknowledges both Alyn and Addam as his sons in front of another named character.', 'Coin flip', '25', 'The family secret finally becomes a family statement.', NULL),
  ('112', '4f607aac-7a70-ccd6-164b-e763bc70e47d', 'Seasmoke Sortie', 'Addam mounts Seasmoke and flies into an active mission, pursuit, or battle.', 'Likely', '20', 'The reliable rider gets deployed.', NULL),
  ('113', '4f607aac-7a70-ccd6-164b-e763bc70e47d', 'Obeys Rhaenyra', 'Addam follows a consequential direct order from Rhaenyra even though it conflicts with Alyn, Corlys, or Baela''s wishes.', 'Coin flip', '25', 'Crown over family.', NULL),
  ('114', '4f607aac-7a70-ccd6-164b-e763bc70e47d', 'Chooses Family', 'Addam knowingly refuses or alters a direct Black order because it would endanger Alyn, Corlys, or Baela.', 'Coin flip', '25', 'Family over crown.', NULL),
  ('115', '4f607aac-7a70-ccd6-164b-e763bc70e47d', 'Backs Alyn', 'Addam takes a concrete action supporting Alyn''s plan concerning Corlys''s captivity or Velaryon command.', 'Coin flip', '25', 'Brotherhood wins the triangle.', NULL),
